export type AgentStatus = 'IDLE' | 'RUNNING' | 'COMPLETED' | 'FAILED' | 'CANCELLED';
export type RunStatus = 'PENDING' | 'RUNNING' | 'COMPLETED' | 'FAILED' | 'CANCELLED';
export type DeploymentStatus = 'PENDING' | 'ACTIVE' | 'FAILED' | 'ROLLED_BACK';
export type PipelineStatus = 'PENDING' | 'RUNNING' | 'WAITING' | 'COMPLETED' | 'FAILED' | 'CANCELLED';
export type StepStatus = 'PENDING' | 'RUNNING' | 'COMPLETED' | 'FAILED' | 'SKIPPED';
export type ToolCategory = 'filesystem' | 'web' | 'code' | 'data' | 'communication' | 'custom';
export type MemoryScope = 'execution' | 'session' | 'agent' | 'pipeline' | 'persistent';
export type StreamTransport = 'sse' | 'chunked';

export interface AgentDefinition {
  id: string;
  name: string;
  description?: string;
  version: string;
  adapter: AdapterConfig;
  tools?: ToolDefinition[];
  systemPrompt?: string;
  tokenBudget?: TokenBudget;
  metadata?: Record<string, unknown>;
  createdAt: Date;
  updatedAt: Date;
}

export interface AdapterConfig {
  provider: 'anthropic' | 'openai' | string;
  model: string;
  apiKey?: string;
  temperature?: number;
  maxTokens?: number;
  tokenBudget?: TokenBudget;
  streaming?: boolean;
  options?: Record<string, unknown>;
}

export interface TokenBudget {
  maxInputTokens?: number;
  maxOutputTokens?: number;
  maxTotalTokens: number;
  onBudgetExceeded: 'hard_stop' | 'warn' | 'graceful_finish';
}

export interface TokenUsage {
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
}

export interface AgentRun {
  id: string;
  agentId: string;
  status: RunStatus;
  input: Record<string, unknown>;
  output?: Record<string, unknown>;
  error?: string;
  tokenUsage?: TokenUsage;
  startedAt?: Date;
  completedAt?: Date;
  createdAt: Date;
  metadata?: Record<string, unknown>;
}

export interface AgentEvent {
  id: string;
  runId: string;
  agentId: string;
  type: AgentEventType;
  data: Record<string, unknown>;
  timestamp: Date;
  sequenceNumber: number;
}

export type AgentEventType =
  | 'run.started'
  | 'run.completed'
  | 'run.failed'
  | 'run.cancelled'
  | 'turn.started'
  | 'turn.completed'
  | 'tool.called'
  | 'tool.result'
  | 'tool.error'
  | 'token.usage'
  | 'budget.exceeded'
  | 'stream.chunk'
  | 'stream.complete'
  | 'pipeline.started'
  | 'pipeline.step.started'
  | 'pipeline.step.completed'
  | 'pipeline.step.failed'
  | 'pipeline.completed'
  | 'pipeline.failed';

export interface ToolDefinition {
  name: string;
  description: string;
  category: ToolCategory;
  inputSchema: Record<string, unknown>;
  idempotent: boolean;
  sensitive?: boolean;
  execute: (input: Record<string, unknown>, context: ToolContext) => Promise<ToolResult>;
}

export interface ToolContext {
  runId: string;
  agentId: string;
  turnNumber: number;
}

export interface ToolResult {
  success: boolean;
  output: unknown;
  error?: string;
  tokenUsage?: TokenUsage;
}

export interface ToolCall {
  id: string;
  name: string;
  input: Record<string, unknown>;
}

export interface Message {
  role: 'user' | 'assistant' | 'tool';
  content: string | ContentBlock[];
  toolCallId?: string;
}

export interface ContentBlock {
  type: 'text' | 'tool_use' | 'tool_result';
  text?: string;
  id?: string;
  name?: string;
  input?: Record<string, unknown>;
  content?: string;
}

export interface PipelineDefinition {
  id: string;
  name: string;
  description?: string;
  steps: PipelineStep[];
  metadata?: Record<string, unknown>;
}

export interface PipelineRun {
  id: string;
  pipelineId: string;
  status: PipelineStatus;
  currentStepIndex: number;
  input: Record<string, unknown>;
  output?: Record<string, unknown>;
  error?: string;
  startedAt?: Date;
  completedAt?: Date;
  createdAt: Date;
}

export type PipelineStep =
  | AgentStep
  | ToolStep
  | BranchStep
  | ParallelStep
  | TransformStep;

export interface AgentStep {
  type: 'agent';
  id: string;
  name: string;
  agentId: string;
  input?: Record<string, unknown>;
}

export interface ToolStep {
  type: 'tool';
  id: string;
  name: string;
  tool: ToolDefinition;
  input?: Record<string, unknown>;
}

export interface BranchStep {
  type: 'branch';
  id: string;
  name: string;
  condition: string;
  trueBranch: PipelineStep[];
  falseBranch: PipelineStep[];
}

export interface ParallelStep {
  type: 'parallel';
  id: string;
  name: string;
  steps: PipelineStep[];
  maxConcurrency?: number;
}

export interface TransformStep {
  type: 'transform';
  id: string;
  name: string;
  transform: (input: Record<string, unknown>) => Record<string, unknown>;
}

export interface Deployment {
  id: string;
  agentId: string;
  version: string;
  status: DeploymentStatus;
  target: 'local' | 'docker' | 'railway';
  rollbackOf?: string;
  config: Record<string, unknown>;
  deployedAt?: Date;
  createdAt: Date;
}

export interface MemoryEntry {
  key: string;
  value: unknown;
  scope: MemoryScope;
  scopeId: string;
  expiresAt?: Date;
  createdAt: Date;
  updatedAt: Date;
}

export interface AgentRunnerConfig {
  adapter: AdapterInstance;
  tools?: ToolDefinition[];
  concurrencyLimit?: number;
  defaultTokenBudget?: TokenBudget;
  onEvent?: (event: AgentEvent) => void | Promise<void>;
}

export interface AdapterInstance {
  readonly provider: string;
  readonly model: string;
  run(messages: Message[], config: AdapterRunConfig): Promise<AdapterResult>;
  stream(messages: Message[], config: AdapterRunConfig): AsyncGenerator<StreamChunk>;
}

export interface AdapterRunConfig {
  systemPrompt?: string;
  tools?: ToolDefinition[];
  maxTokens?: number;
  temperature?: number;
}

export interface AdapterResult {
  content: string;
  toolCalls: ToolCall[];
  stopReason: 'end_turn' | 'tool_use' | 'max_tokens' | 'stop_sequence';
  usage: TokenUsage;
}

export interface StreamChunk {
  type: 'text' | 'tool_use' | 'usage' | 'stop';
  text?: string;
  toolCall?: Partial<ToolCall>;
  usage?: Partial<TokenUsage>;
  stopReason?: string;
}

export interface PluginDefinition {
  name: string;
  version: string;
  trusted: true;
  tools?: ToolDefinition[];
  onLoad?: (context: PluginContext) => Promise<void>;
  onUnload?: () => Promise<void>;
}

export interface PluginContext {
  registerTool: (tool: ToolDefinition) => void;
}

export interface HealthCheck {
  status: 'ok' | 'degraded' | 'error';
  version: string;
  checks: {
    database: 'ok' | 'error';
    adapters: Record<string, 'ok' | 'error'>;
    concurrency: { current: number; limit: number };
  };
  timestamp: Date;
}

export type AgentError =
  | { code: 'TOOL_ERROR'; message: string; toolName: string; cause?: unknown }
  | { code: 'ADAPTER_ERROR'; message: string; provider: string; cause?: unknown }
  | { code: 'BUDGET_EXCEEDED'; message: string; usage: { inputTokens: number; outputTokens: number; totalTokens: number }; budget: number }
  | { code: 'CONCURRENCY_LIMIT'; message: string; limit: number; current: number }
  | { code: 'VALIDATION_ERROR'; message: string; field?: string; cause?: unknown }
  | { code: 'PIPELINE_ERROR'; message: string; stepId?: string; cause?: unknown }
  | { code: 'RUNTIME_ERROR'; message: string; cause?: unknown }
  | { code: 'NOT_FOUND'; message: string; resource: string; id: string }
  | { code: 'UNAUTHORIZED'; message: string }
  | { code: 'PLUGIN_ERROR'; message: string; pluginName: string; cause?: unknown };

export class AgentOSError extends Error {
  readonly agentError: AgentError;

  constructor(agentError: AgentError) {
    super(agentError.message);
    this.name = 'AgentOSError';
    this.agentError = agentError;
  }

  static toolError(toolName: string, message: string, cause?: unknown): AgentOSError {
    return new AgentOSError({ code: 'TOOL_ERROR', message, toolName, cause });
  }

  static adapterError(provider: string, message: string, cause?: unknown): AgentOSError {
    return new AgentOSError({ code: 'ADAPTER_ERROR', message, provider, cause });
  }

  static budgetExceeded(
    usage: { inputTokens: number; outputTokens: number; totalTokens: number },
    budget: number
  ): AgentOSError {
    return new AgentOSError({
      code: 'BUDGET_EXCEEDED',
      message: `Token budget exceeded: used ${usage.totalTokens}, limit ${budget}`,
      usage,
      budget,
    });
  }

  static concurrencyLimit(limit: number, current: number): AgentOSError {
    return new AgentOSError({
      code: 'CONCURRENCY_LIMIT',
      message: `Concurrency limit reached: ${current}/${limit} active runs`,
      limit,
      current,
    });
  }

  static validationError(message: string, field?: string): AgentOSError {
    return new AgentOSError({ code: 'VALIDATION_ERROR', message, field });
  }

  static pipelineError(message: string, stepId?: string, cause?: unknown): AgentOSError {
    return new AgentOSError({ code: 'PIPELINE_ERROR', message, stepId, cause });
  }

  static runtimeError(message: string, cause?: unknown): AgentOSError {
    return new AgentOSError({ code: 'RUNTIME_ERROR', message, cause });
  }

  static notFound(resource: string, id: string): AgentOSError {
    return new AgentOSError({
      code: 'NOT_FOUND',
      message: `${resource} with id '${id}' not found`,
      resource,
      id,
    });
  }

  static pluginError(pluginName: string, message: string, cause?: unknown): AgentOSError {
    return new AgentOSError({ code: 'PLUGIN_ERROR', message, pluginName, cause });
  }
}

export * from './types.js';
export * from './errors.js';

export const AGENT_OS_VERSION = '2.0.0';

export const CONCURRENCY_DEFAULTS = {
  maxConcurrentRuns: 50,
  maxConcurrentToolCalls: 10,
} as const;

export const TOKEN_BUDGET_DEFAULTS = {
  maxTotalTokens: 100_000,
  onBudgetExceeded: 'hard_stop' as const,
};

export const SUPPORTED_DEPLOYMENT_TARGETS = ['local', 'docker', 'railway'] as const;
export type DeploymentTarget = (typeof SUPPORTED_DEPLOYMENT_TARGETS)[number];

import { sqliteTable, text, integer, real } from 'drizzle-orm/sqlite-core';

export const agentRuns = sqliteTable('agent_runs', {
  id: text('id').primaryKey(),
  agentId: text('agent_id').notNull(),
  status: text('status', {
    enum: ['PENDING', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED'],
  })
    .notNull()
    .default('PENDING'),
  inputJson: text('input_json').notNull().default('{}'),
  outputJson: text('output_json'),
  errorMessage: text('error_message'),
  inputTokens: integer('input_tokens').notNull().default(0),
  outputTokens: integer('output_tokens').notNull().default(0),
  totalTokens: integer('total_tokens').notNull().default(0),
  startedAt: integer('started_at', { mode: 'timestamp' }),
  completedAt: integer('completed_at', { mode: 'timestamp' }),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  metadataJson: text('metadata_json'),
});

export const agentEvents = sqliteTable('agent_events', {
  id: text('id').primaryKey(),
  runId: text('run_id').notNull(),
  agentId: text('agent_id').notNull(),
  type: text('type').notNull(),
  dataJson: text('data_json').notNull().default('{}'),
  timestamp: integer('timestamp', { mode: 'timestamp' }).notNull(),
  sequenceNumber: integer('sequence_number').notNull(),
});

export const agentDefinitions = sqliteTable('agent_definitions', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  description: text('description'),
  version: text('version').notNull().default('1.0.0'),
  configJson: text('config_json').notNull().default('{}'),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
});

export const deployments = sqliteTable('deployments', {
  id: text('id').primaryKey(),
  agentId: text('agent_id').notNull(),
  version: text('version').notNull(),
  status: text('status', {
    enum: ['PENDING', 'ACTIVE', 'FAILED', 'ROLLED_BACK'],
  })
    .notNull()
    .default('PENDING'),
  target: text('target', { enum: ['local', 'docker', 'railway'] })
    .notNull()
    .default('local'),
  rollbackOf: text('rollback_of'),
  configJson: text('config_json').notNull().default('{}'),
  deployedAt: integer('deployed_at', { mode: 'timestamp' }),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
});

export const memoryEntries = sqliteTable('memory_entries', {
  id: text('id').primaryKey(),
  key: text('key').notNull(),
  valueJson: text('value_json').notNull(),
  scope: text('scope', {
    enum: ['execution', 'session', 'agent', 'pipeline', 'persistent'],
  }).notNull(),
  scopeId: text('scope_id').notNull(),
  expiresAt: integer('expires_at', { mode: 'timestamp' }),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
});

export type AgentRunRow = typeof agentRuns.$inferSelect;
export type NewAgentRunRow = typeof agentRuns.$inferInsert;
export type AgentEventRow = typeof agentEvents.$inferSelect;
export type NewAgentEventRow = typeof agentEvents.$inferInsert;
export type AgentDefinitionRow = typeof agentDefinitions.$inferSelect;
export type DeploymentRow = typeof deployments.$inferSelect;
