import Database from 'better-sqlite3';
import { drizzle } from 'drizzle-orm/better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import { mkdirSync } from 'fs';
import { dirname, resolve } from 'path';
import { fileURLToPath } from 'url';
import * as schema from './schema.js';

export type AgentOSDb = ReturnType<typeof createDb>;

export function createDb(dbPath = './agent-os.db'): ReturnType<typeof drizzle<typeof schema>> {
  const resolved = resolve(dbPath);
  mkdirSync(dirname(resolved), { recursive: true });
  const sqlite = new Database(resolved);
  sqlite.pragma('journal_mode = WAL');
  sqlite.pragma('foreign_keys = ON');
  return drizzle(sqlite, { schema });
}

export function createAndMigrateDb(dbPath = './agent-os.db'): ReturnType<typeof drizzle<typeof schema>> {
  const db = createDb(dbPath);
  const __dirname = dirname(fileURLToPath(import.meta.url));
  try {
    migrate(db, { migrationsFolder: resolve(__dirname, '../migrations') });
  } catch {
  }
  return db;
}

export { schema };

import type {
  AdapterInstance,
  AdapterRunConfig,
  AdapterResult,
  Message,
  StreamChunk,
  TokenUsage,
} from '@agent-os/core';

export abstract class BaseAdapter implements AdapterInstance {
  abstract readonly provider: string;
  abstract readonly model: string;

  abstract run(messages: Message[], config: AdapterRunConfig): Promise<AdapterResult>;
  abstract stream(messages: Message[], config: AdapterRunConfig): AsyncGenerator<StreamChunk>;

  protected mergeUsage(a: Partial<TokenUsage>, b: Partial<TokenUsage>): TokenUsage {
    return {
      inputTokens: (a.inputTokens ?? 0) + (b.inputTokens ?? 0),
      outputTokens: (a.outputTokens ?? 0) + (b.outputTokens ?? 0),
      totalTokens: (a.totalTokens ?? 0) + (b.totalTokens ?? 0),
    };
  }
}

import Anthropic from '@anthropic-ai/sdk';
import type {
  AdapterRunConfig,
  AdapterResult,
  Message,
  StreamChunk,
  ToolCall,
  ToolDefinition,
} from '@agent-os/core';
import { AgentOSError } from '@agent-os/core';
import { BaseAdapter } from './base.js';

export interface AnthropicAdapterConfig {
  apiKey?: string;
  model?: string;
  maxTokens?: number;
  temperature?: number;
}

export class AnthropicAdapter extends BaseAdapter {
  readonly provider = 'anthropic';
  readonly model: string;
  private readonly client: Anthropic;
  private readonly defaultMaxTokens: number;
  private readonly defaultTemperature: number;

  constructor(config: AnthropicAdapterConfig = {}) {
    super();
    const apiKey = config.apiKey ?? process.env['ANTHROPIC_API_KEY'];
    if (!apiKey) {
      throw AgentOSError.adapterError('anthropic', 'ANTHROPIC_API_KEY is required');
    }
    this.client = new Anthropic({ apiKey });
    this.model = config.model ?? 'claude-3-5-sonnet-20241022';
    this.defaultMaxTokens = config.maxTokens ?? 4096;
    this.defaultTemperature = config.temperature ?? 1.0;
  }

  async run(messages: Message[], config: AdapterRunConfig): Promise<AdapterResult> {
    try {
      const response = await this.client.messages.create({
        model: this.model,
        max_tokens: config.maxTokens ?? this.defaultMaxTokens,
        temperature: config.temperature ?? this.defaultTemperature,
        system: config.systemPrompt,
        messages: this.formatMessages(messages),
        tools: config.tools ? this.formatTools(config.tools) : undefined,
      });

      const content = response.content
        .filter((b) => b.type === 'text')
        .map((b) => (b.type === 'text' ? b.text : ''))
        .join('');

      const toolCalls: ToolCall[] = response.content
        .filter((b) => b.type === 'tool_use')
        .map((b) => {
          if (b.type !== 'tool_use') return null;
          return {
            id: b.id,
            name: b.name,
            input: b.input as Record<string, unknown>,
          };
        })
        .filter((tc): tc is ToolCall => tc !== null);

      return {
        content,
        toolCalls,
        stopReason: this.mapStopReason(response.stop_reason),
        usage: {
          inputTokens: response.usage.input_tokens,
          outputTokens: response.usage.output_tokens,
          totalTokens: response.usage.input_tokens + response.usage.output_tokens,
        },
      };
    } catch (err) {
      throw AgentOSError.adapterError('anthropic', `API call failed: ${String(err)}`, err);
    }
  }

  async *stream(messages: Message[], config: AdapterRunConfig): AsyncGenerator<StreamChunk> {
    try {
      const stream = await this.client.messages.stream({
        model: this.model,
        max_tokens: config.maxTokens ?? this.defaultMaxTokens,
        temperature: config.temperature ?? this.defaultTemperature,
        system: config.systemPrompt,
        messages: this.formatMessages(messages),
        tools: config.tools ? this.formatTools(config.tools) : undefined,
      });

      for await (const event of stream) {
        if (event.type === 'content_block_delta') {
          if (event.delta.type === 'text_delta') {
            yield { type: 'text', text: event.delta.text };
          }
        } else if (event.type === 'message_delta' && event.usage) {
          yield {
            type: 'usage',
            usage: {
              outputTokens: event.usage.output_tokens,
            },
          };
        } else if (event.type === 'message_stop') {
          yield { type: 'stop', stopReason: 'end_turn' };
        }
      }
    } catch (err) {
      throw AgentOSError.adapterError('anthropic', `Streaming failed: ${String(err)}`, err);
    }
  }

  private formatMessages(messages: Message[]): Anthropic.MessageParam[] {
    return messages
      .filter((m) => m.role !== 'tool')
      .map((m) => ({
        role: m.role as 'user' | 'assistant',
        content: typeof m.content === 'string' ? m.content : String(m.content),
      }));
  }

  private formatTools(tools: ToolDefinition[]): Anthropic.Tool[] {
    return tools.map((t) => ({
      name: t.name,
      description: t.description,
      input_schema: {
        type: 'object' as const,
        ...(t.inputSchema as object),
      },
    }));
  }

  private mapStopReason(reason: string | null): AdapterResult['stopReason'] {
    switch (reason) {
      case 'tool_use': return 'tool_use';
      case 'max_tokens': return 'max_tokens';
      case 'stop_sequence': return 'stop_sequence';
      default: return 'end_turn';
    }
  }
}

import type { AgentEvent, AgentEventType } from '@agent-os/core';

type EventHandler = (event: AgentEvent) => void | Promise<void>;

export class EventBus {
  private readonly handlers = new Map<string, Set<EventHandler>>();
  private readonly allHandlers = new Set<EventHandler>();
  private sequenceCounters = new Map<string, number>();

  on(type: AgentEventType | '*', handler: EventHandler): () => void {
    if (type === '*') {
      this.allHandlers.add(handler);
      return () => this.allHandlers.delete(handler);
    }
    if (!this.handlers.has(type)) {
      this.handlers.set(type, new Set());
    }
    this.handlers.get(type)!.add(handler);
    return () => this.handlers.get(type)?.delete(handler);
  }

  async emit(event: Omit<AgentEvent, 'sequenceNumber'>): Promise<AgentEvent> {
    const counter = this.sequenceCounters.get(event.runId) ?? 0;
    this.sequenceCounters.set(event.runId, counter + 1);

    const fullEvent: AgentEvent = { ...event, sequenceNumber: counter };

    const typeHandlers = this.handlers.get(event.type) ?? new Set();
    const promises: Promise<void>[] = [];

    for (const handler of [...typeHandlers, ...this.allHandlers]) {
      const result = handler(fullEvent);
      if (result instanceof Promise) promises.push(result);
    }

    await Promise.allSettled(promises);
    return fullEvent;
  }

  clearRun(runId: string): void {
    this.sequenceCounters.delete(runId);
  }

  removeAllHandlers(): void {
    this.handlers.clear();
    this.allHandlers.clear();
    this.sequenceCounters.clear();
  }
}

import type { TokenBudget, TokenUsage } from '@agent-os/core';
import { AgentOSError } from '@agent-os/core';

export class TokenTracker {
  private inputTokens = 0;
  private outputTokens = 0;

  constructor(private readonly budget: TokenBudget | undefined) {}

  get usage(): TokenUsage {
    return {
      inputTokens: this.inputTokens,
      outputTokens: this.outputTokens,
      totalTokens: this.inputTokens + this.outputTokens,
    };
  }

  accumulate(usage: TokenUsage): void {
    this.inputTokens += usage.inputTokens;
    this.outputTokens += usage.outputTokens;

    if (this.budget) {
      this.checkBudget();
    }
  }

  private checkBudget(): void {
    if (!this.budget) return;
    const total = this.inputTokens + this.outputTokens;

    if (this.budget.maxInputTokens !== undefined && this.inputTokens > this.budget.maxInputTokens) {
      if (this.budget.onBudgetExceeded === 'hard_stop') {
        throw AgentOSError.budgetExceeded(this.usage, this.budget.maxInputTokens);
      }
    }

    if (this.budget.maxOutputTokens !== undefined && this.outputTokens > this.budget.maxOutputTokens) {
      if (this.budget.onBudgetExceeded === 'hard_stop') {
        throw AgentOSError.budgetExceeded(this.usage, this.budget.maxOutputTokens);
      }
    }

    if (total > this.budget.maxTotalTokens) {
      if (this.budget.onBudgetExceeded === 'hard_stop') {
        throw AgentOSError.budgetExceeded(this.usage, this.budget.maxTotalTokens);
      }
    }
  }

  isBudgetExceeded(): boolean {
    if (!this.budget) return false;
    const total = this.inputTokens + this.outputTokens;
    return total > this.budget.maxTotalTokens;
  }
}

import { v4 as uuidv4 } from 'uuid';
import pLimit from 'p-limit';
import type {
  AgentDefinition,
  AgentEvent,
  AgentRun,
  AgentRunnerConfig,
  Message,
  ToolCall,
  ToolDefinition,
} from '@agent-os/core';
import { AgentOSError, CONCURRENCY_DEFAULTS } from '@agent-os/core';
import { EventBus } from './event-bus.js';
import { TokenTracker } from './token-tracker.js';

export interface RunInput {
  agentId: string;
  input: Record<string, unknown>;
  systemPrompt?: string;
  tokenBudget?: AgentDefinition['adapter']['tokenBudget'];
  metadata?: Record<string, unknown>;
}

export interface RunResult {
  run: AgentRun;
  events: AgentEvent[];
}

const MAX_TURNS = 20;

export class AgentRunner {
  private readonly eventBus: EventBus;
  private readonly limit: ReturnType<typeof pLimit>;
  private activeRuns = 0;
  private readonly maxConcurrency: number;

  constructor(private readonly config: AgentRunnerConfig) {
    this.eventBus = new EventBus();
    this.maxConcurrency = config.concurrencyLimit ?? CONCURRENCY_DEFAULTS.maxConcurrentRuns;
    this.limit = pLimit(this.maxConcurrency);

    if (config.onEvent) {
      this.eventBus.on('*', config.onEvent);
    }
  }

  on(handler: (event: AgentEvent) => void | Promise<void>): () => void {
    return this.eventBus.on('*', handler);
  }

  async run(input: RunInput): Promise<RunResult> {
    if (this.activeRuns >= this.maxConcurrency) {
      throw AgentOSError.concurrencyLimit(this.maxConcurrency, this.activeRuns);
    }

    return this.limit(() => this.executeRun(input));
  }

  private async executeRun(input: RunInput): Promise<RunResult> {
    const runId = uuidv4();
    const events: AgentEvent[] = [];
    const tracker = new TokenTracker(input.tokenBudget ?? this.config.defaultTokenBudget);

    const collect = (event: AgentEvent) => events.push(event);
    const off = this.eventBus.on('*', collect);

    this.activeRuns++;

    const run: AgentRun = {
      id: runId,
      agentId: input.agentId,
      status: 'RUNNING',
      input: input.input,
      createdAt: new Date(),
      startedAt: new Date(),
      metadata: input.metadata,
    };

    try {
      await this.eventBus.emit({
        id: uuidv4(),
        runId,
        agentId: input.agentId,
        type: 'run.started',
        data: { input: input.input },
        timestamp: new Date(),
      });

      const messages: Message[] = [
        { role: 'user', content: JSON.stringify(input.input) },
      ];

      let turn = 0;

      while (turn < MAX_TURNS) {
        turn++;

        await this.eventBus.emit({
          id: uuidv4(),
          runId,
          agentId: input.agentId,
          type: 'turn.started',
          data: { turn },
          timestamp: new Date(),
        });

        const result = await this.config.adapter.run(messages, {
          systemPrompt: input.systemPrompt,
          tools: this.config.tools,
          maxTokens: this.config.adapter.run.length,
        });

        tracker.accumulate(result.usage);

        await this.eventBus.emit({
          id: uuidv4(),
          runId,
          agentId: input.agentId,
          type: 'token.usage',
          data: { usage: result.usage, cumulative: tracker.usage },
          timestamp: new Date(),
        });

        await this.eventBus.emit({
          id: uuidv4(),
          runId,
          agentId: input.agentId,
          type: 'turn.completed',
          data: { turn, stopReason: result.stopReason, content: result.content },
          timestamp: new Date(),
        });

        if (result.stopReason === 'end_turn' || result.toolCalls.length === 0) {
          run.status = 'COMPLETED';
          run.output = { content: result.content };
          run.tokenUsage = tracker.usage;
          run.completedAt = new Date();

          await this.eventBus.emit({
            id: uuidv4(),
            runId,
            agentId: input.agentId,
            type: 'run.completed',
            data: { output: run.output, tokenUsage: tracker.usage },
            timestamp: new Date(),
          });

          break;
        }

        if (result.toolCalls.length > 0) {
          messages.push({ role: 'assistant', content: result.content });
          const toolResults = await this.executeToolCalls(
            result.toolCalls,
            runId,
            input.agentId,
            turn
          );
          messages.push(...toolResults);
        }
      }

      if (turn >= MAX_TURNS && run.status === 'RUNNING') {
        run.status = 'FAILED';
        run.error = `Exceeded maximum turns (${MAX_TURNS})`;
        run.completedAt = new Date();
        await this.eventBus.emit({
          id: uuidv4(),
          runId,
          agentId: input.agentId,
          type: 'run.failed',
          data: { error: run.error },
          timestamp: new Date(),
        });
      }
    } catch (err) {
      run.status = 'FAILED';
      run.error = err instanceof Error ? err.message : String(err);
      run.completedAt = new Date();
      run.tokenUsage = tracker.usage;

      const isBudget = err instanceof AgentOSError && err.agentError.code === 'BUDGET_EXCEEDED';

      await this.eventBus.emit({
        id: uuidv4(),
        runId,
        agentId: input.agentId,
        type: isBudget ? 'budget.exceeded' : 'run.failed',
        data: { error: run.error },
        timestamp: new Date(),
      });
    } finally {
      this.activeRuns--;
      off();
      this.eventBus.clearRun(runId);
    }

    return { run, events };
  }

  private async executeToolCalls(
    toolCalls: ToolCall[],
    runId: string,
    agentId: string,
    turn: number
  ): Promise<Message[]> {
    const toolMessages: Message[] = [];
    const tools = this.config.tools ?? [];

    for (const tc of toolCalls) {
      const tool = tools.find((t) => t.name === tc.name);

      await this.eventBus.emit({
        id: uuidv4(),
        runId,
        agentId,
        type: 'tool.called',
        data: { toolName: tc.name, input: tc.input, toolCallId: tc.id },
        timestamp: new Date(),
      });

      if (!tool) {
        await this.eventBus.emit({
          id: uuidv4(),
          runId,
          agentId,
          type: 'tool.error',
          data: { toolName: tc.name, error: `Tool '${tc.name}' not found` },
          timestamp: new Date(),
        });
        toolMessages.push({
          role: 'tool',
          content: `Error: tool '${tc.name}' not found`,
          toolCallId: tc.id,
        });
        continue;
      }

      try {
        const result = await tool.execute(tc.input, { runId, agentId, turnNumber: turn });

        await this.eventBus.emit({
          id: uuidv4(),
          runId,
          agentId,
          type: 'tool.result',
          data: { toolName: tc.name, success: result.success, output: result.output },
          timestamp: new Date(),
        });

        toolMessages.push({
          role: 'tool',
          content: JSON.stringify(result.output),
          toolCallId: tc.id,
        });
      } catch (err) {
        const error = err instanceof Error ? err.message : String(err);
        await this.eventBus.emit({
          id: uuidv4(),
          runId,
          agentId,
          type: 'tool.error',
          data: { toolName: tc.name, error },
          timestamp: new Date(),
        });
        toolMessages.push({
          role: 'tool',
          content: `Error: ${error}`,
          toolCallId: tc.id,
        });
      }
    }

    return toolMessages;
  }

  get stats() {
    return {
      activeRuns: this.activeRuns,
      maxConcurrency: this.maxConcurrency,
    };
  }
}

