#!/usr/bin/env node
import { program } from 'commander';
import chalk from 'chalk';
import ora from 'ora';
import { createDb } from '@agent-os/db';
import { agentRuns, agentEvents, agentDefinitions } from '@agent-os/db';
import { desc, eq } from 'drizzle-orm';
import { AGENT_OS_VERSION } from '@agent-os/core';
import { execSync } from 'child_process';
import { existsSync, mkdirSync, writeFileSync } from 'fs';
import { resolve } from 'path';

program
  .name('agos')
  .description('Agent-OS CLI — manage and run AI agents')
  .version(AGENT_OS_VERSION);

program
  .command('init [project-name]')
  .description('Scaffold a new Agent-OS project')
  .option('--template <template>', 'project template (basic|pipeline)', 'basic')
  .action((projectName: string = 'my-agent', options: { template: string }) => {
    const spinner = ora(`Creating project '${projectName}'...`).start();

    try {
      const dir = resolve(process.cwd(), projectName);
      if (existsSync(dir)) {
        spinner.fail(`Directory '${projectName}' already exists`);
        process.exit(1);
      }

      mkdirSync(dir, { recursive: true });
      mkdirSync(resolve(dir, 'src'), { recursive: true });

      writeFileSync(
        resolve(dir, 'package.json'),
        JSON.stringify(
          {
            name: projectName,
            version: '0.1.0',
            type: 'module',
            scripts: { start: 'node src/agent.js', build: 'tsc' },
            dependencies: {
              '@agent-os/runtime': `^${AGENT_OS_VERSION}`,
              '@agent-os/adapters': `^${AGENT_OS_VERSION}`,
            },
          },
          null,
          2
        )
      );

      writeFileSync(
        resolve(dir, 'src/agent.ts'),
        `import { AgentRunner } from '@agent-os/runtime';
import { AnthropicAdapter } from '@agent-os/adapters';

const runner = new AgentRunner({
  adapter: new AnthropicAdapter({ model: 'claude-3-5-sonnet-20241022' }),
  concurrencyLimit: 10,
});

const { run, events } = await runner.run({
  agentId: '${projectName}',
  input: { task: 'Hello! Tell me about Agent-OS.' },
});

console.log('Run:', run.status);
console.log('Output:', run.output);
console.log('Tokens used:', run.tokenUsage?.totalTokens);
`
      );

      writeFileSync(resolve(dir, '.env'), 'ANTHROPIC_API_KEY=your-key-here\n');

      writeFileSync(
        resolve(dir, 'tsconfig.json'),
        JSON.stringify(
          {
            compilerOptions: {
              target: 'ES2022',
              module: 'NodeNext',
              moduleResolution: 'NodeNext',
              strict: true,
              outDir: 'dist',
            },
            include: ['src'],
          },
          null,
          2
        )
      );

      spinner.succeed(chalk.green(`Project '${projectName}' created!`));
      console.log();
      console.log(chalk.bold('Next steps:'));
      console.log(`  cd ${projectName}`);
      console.log('  pnpm install');
      console.log(`  echo "ANTHROPIC_API_KEY=sk-..." >> .env`);
      console.log('  pnpm start');
    } catch (err) {
      spinner.fail(`Failed: ${String(err)}`);
      process.exit(1);
    }
  });

program
  .command('list')
  .alias('ls')
  .description('List recent agent runs')
  .option('-n, --count <count>', 'number of runs to show', '20')
  .option('--json', 'output as JSON')
  .action(async (options: { count: string; json: boolean }) => {
    try {
      const db = createDb();
      const runs = await db
        .select()
        .from(agentRuns)
        .orderBy(desc(agentRuns.createdAt))
        .limit(parseInt(options.count, 10));

      if (options.json) {
        console.log(JSON.stringify(runs, null, 2));
        return;
      }

      if (runs.length === 0) {
        console.log(chalk.gray('No runs found. Use `agos run` to start one.'));
        return;
      }

      console.log(chalk.bold('\nRecent Agent Runs\n'));
      for (const run of runs) {
        const statusColor =
          run.status === 'COMPLETED'
            ? chalk.green
            : run.status === 'FAILED'
              ? chalk.red
              : run.status === 'RUNNING'
                ? chalk.yellow
                : chalk.gray;

        const ts = run.createdAt
          ? new Date(run.createdAt).toLocaleString()
          : 'unknown';

        console.log(
          `${chalk.cyan(run.id.slice(0, 8))}  ${statusColor(run.status.padEnd(10))}  ${chalk.gray(run.agentId.padEnd(20))}  ${chalk.gray(ts)}`
        );
      }
      console.log();
    } catch (err) {
      console.error(chalk.red(`Error: ${String(err)}`));
      process.exit(1);
    }
  });

program
  .command('logs <runId>')
  .description('Show events for a specific run')
  .option('--json', 'output as JSON')
  .option('--tail', 'stream live events (not yet supported)')
  .action(async (runId: string, options: { json: boolean; tail: boolean }) => {
    try {
      const db = createDb();

      const [run] = await db
        .select()
        .from(agentRuns)
        .where(eq(agentRuns.id, runId))
        .limit(1);

      if (!run) {
        console.error(chalk.red(`Run '${runId}' not found`));
        process.exit(1);
      }

      const events = await db
        .select()
        .from(agentEvents)
        .where(eq(agentEvents.runId, runId))
        .orderBy(agentEvents.sequenceNumber);

      if (options.json) {
        console.log(JSON.stringify({ run, events }, null, 2));
        return;
      }

      console.log(chalk.bold(`\nRun: ${run.id}`));
      console.log(`Agent: ${chalk.cyan(run.agentId)}`);
      console.log(`Status: ${run.status}`);
      console.log(`Created: ${run.createdAt ? new Date(run.createdAt).toLocaleString() : 'N/A'}`);
      if (run.totalTokens) console.log(`Tokens: ${run.totalTokens}`);
      console.log(chalk.bold('\nEvents:'));

      for (const event of events) {
        const ts = event.timestamp
          ? new Date(event.timestamp).toISOString().slice(11, 23)
          : '??:??:??.???';
        const data = JSON.parse(event.dataJson ?? '{}') as Record<string, unknown>;
        const preview = Object.keys(data).length > 0
          ? '  ' + chalk.gray(JSON.stringify(data).slice(0, 80))
          : '';

        console.log(`${chalk.gray(ts)}  ${chalk.cyan(event.type)}${preview}`);
      }
      console.log();
    } catch (err) {
      console.error(chalk.red(`Error: ${String(err)}`));
      process.exit(1);
    }
  });

program
  .command('doctor')
  .description('Check Agent-OS environment and dependencies')
  .action(async () => {
    console.log(chalk.bold('\nAgent-OS Doctor\n'));

    const checks: Array<{ label: string; check: () => string | Promise<string> }> = [
      {
        label: 'Node.js version',
        check: () => {
          const [major] = process.version.slice(1).split('.').map(Number);
          if ((major ?? 0) < 20) return `${process.version} ⚠ (requires >=20)`;
          return `${process.version} ✓`;
        },
      },
      {
        label: 'ANTHROPIC_API_KEY',
        check: () => {
          const key = process.env['ANTHROPIC_API_KEY'];
          if (!key) return 'not set ✗';
          return `set (${key.slice(0, 7)}...) ✓`;
        },
      },
      {
        label: 'Database',
        check: async () => {
          try {
            createDb();
            return 'SQLite OK ✓';
          } catch (err) {
            return `Error: ${String(err)} ✗`;
          }
        },
      },
      {
        label: 'TypeScript (tsc)',
        check: () => {
          try {
            const out = execSync('tsc --version', { encoding: 'utf8' }).trim();
            return `${out} ✓`;
          } catch {
            return 'not found ✗';
          }
        },
      },
    ];

    for (const { label, check } of checks) {
      const result = await Promise.resolve(check());
      const ok = result.includes('✓');
      const icon = ok ? chalk.green('✓') : chalk.red('✗');
      console.log(`  ${icon}  ${label.padEnd(25)} ${result.replace(/[✓✗]/g, '').trim()}`);
    }

    console.log();
  });

program.parse();

import express from 'express';
import cors from 'cors';
import { createRequire } from 'module';
import { fileURLToPath } from 'url';
import { dirname, resolve } from 'path';
import { existsSync } from 'fs';
import Database from 'better-sqlite3';
import { drizzle } from 'drizzle-orm/better-sqlite3';
import { desc, eq, sql } from 'drizzle-orm';
import { v4 as uuidv4 } from 'uuid';

const __dirname = dirname(fileURLToPath(import.meta.url));

const DB_PATH = process.env.AGENT_OS_DB ?? resolve(__dirname, '../../agent-os.db');

function getDb() {
  const db_sqlite = new Database(DB_PATH);
  db_sqlite.pragma('journal_mode = WAL');
  db_sqlite.pragma('foreign_keys = ON');

  db_sqlite.exec(`
    CREATE TABLE IF NOT EXISTS agent_runs (
      id TEXT PRIMARY KEY,
      agent_id TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'PENDING',
      input_json TEXT NOT NULL DEFAULT '{}',
      output_json TEXT,
      error_message TEXT,
      input_tokens INTEGER NOT NULL DEFAULT 0,
      output_tokens INTEGER NOT NULL DEFAULT 0,
      total_tokens INTEGER NOT NULL DEFAULT 0,
      started_at INTEGER,
      completed_at INTEGER,
      created_at INTEGER NOT NULL,
      metadata_json TEXT
    );
    CREATE TABLE IF NOT EXISTS agent_events (
      id TEXT PRIMARY KEY,
      run_id TEXT NOT NULL,
      agent_id TEXT NOT NULL,
      type TEXT NOT NULL,
      data_json TEXT NOT NULL DEFAULT '{}',
      timestamp INTEGER NOT NULL,
      sequence_number INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS agent_definitions (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      description TEXT,
      version TEXT NOT NULL DEFAULT '1.0.0',
      config_json TEXT NOT NULL DEFAULT '{}',
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );
  `);

  return db_sqlite;
}

const app = express();
app.use(cors());
app.use(express.json());

const sseClients = new Set();

app.get('/api/health', (_req, res) => {
