    timestamp: new Date().toISOString(),
  });
});

app.get('/api/runs', (req, res) => {
  try {
    const db = getDb();
    const limit = parseInt(req.query.limit ?? '50', 10);
    const runs = db.prepare(
      `SELECT * FROM agent_runs ORDER BY created_at DESC LIMIT ?`
    ).all(limit);
