app.get('/api/stats', (_req, res) => {
  try {
    const db = getDb();
    const total = db.prepare(`SELECT COUNT(*) as count FROM agent_runs`).get();
    const byStatus = db.prepare(
      `SELECT status, COUNT(*) as count FROM agent_runs GROUP BY status`
