    const totalTokens = db.prepare(
      `SELECT SUM(total_tokens) as total FROM agent_runs`
    ).get();
    const recentEvents = db.prepare(
      `SELECT COUNT(*) as count FROM agent_events WHERE timestamp > ?`
    ).get(Date.now() - 3600000);

    res.json({
      runs: { total: total.count, byStatus },
      tokens: { total: totalTokens.total ?? 0 },
      events: { lastHour: recentEvents.count },
    });
  } catch (err) {
    res.status(500).json({ error: String(err) });
  }
});

app.post('/api/runs/demo', (req, res) => {
  try {
    const db = getDb();
    const runId = uuidv4();
    const now = Date.now();
    const statuses = ['COMPLETED', 'COMPLETED', 'COMPLETED', 'FAILED', 'RUNNING'];
    const agents = ['summarizer-agent', 'code-reviewer', 'data-analyst', 'research-agent'];
    const status = statuses[Math.floor(Math.random() * statuses.length)];
    const agentId = agents[Math.floor(Math.random() * agents.length)];
    const tokens = Math.floor(Math.random() * 8000) + 500;

    db.prepare(`
      INSERT INTO agent_runs (id, agent_id, status, input_json, output_json, input_tokens, output_tokens, total_tokens, started_at, completed_at, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      runId, agentId, status,
      JSON.stringify({ task: 'Demo task ' + runId.slice(0, 6) }),
      status === 'COMPLETED' ? JSON.stringify({ content: 'Task completed successfully.' }) : null,
      Math.floor(tokens * 0.6), Math.floor(tokens * 0.4), tokens,
      now - 5000, status !== 'RUNNING' ? now : null, now
    );

    const eventTypes = ['run.started', 'turn.started', 'turn.completed', 'token.usage', 'run.completed'];
    eventTypes.forEach((type, i) => {
      db.prepare(`
        INSERT INTO agent_events (id, run_id, agent_id, type, data_json, timestamp, sequence_number)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).run(uuidv4(), runId, agentId, type, JSON.stringify({ demo: true }), now + i * 100, i);
    });

    broadcast({ type: 'run.created', data: { runId, agentId, status } });
    res.json({ runId, status });
  } catch (err) {
    res.status(500).json({ error: String(err) });
  }
});

app.get('/api/sse', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.flushHeaders();

  const client = { res };
  sseClients.add(client);

  res.write(`data: ${JSON.stringify({ type: 'connected', timestamp: new Date().toISOString() })}\n\n`);

  const heartbeat = setInterval(() => {
    res.write(`: heartbeat\n\n`);
  }, 15000);

  req.on('close', () => {
    clearInterval(heartbeat);
    sseClients.delete(client);
  });
});

function broadcast(payload) {
  const data = `data: ${JSON.stringify(payload)}\n\n`;
  for (const client of sseClients) {
    try {
      client.res.write(data);
    } catch {
      sseClients.delete(client);
    }
  }
}

