export class ExecutionMemory {
  private readonly store = new Map<string, unknown>();
  readonly runId: string;

  constructor(runId: string) {
    this.runId = runId;
  }

  get(key: string): unknown {
    return this.store.get(key);
  }

  set(key: string, value: unknown): void {
    this.store.set(key, value);
  }

  has(key: string): boolean {
    return this.store.has(key);
  }

  delete(key: string): boolean {
    return this.store.delete(key);
  }

  clear(): void {
    this.store.clear();
  }

  snapshot(): Record<string, unknown> {
    return Object.fromEntries(this.store);
  }

  restore(snapshot: Record<string, unknown>): void {
    this.store.clear();
    for (const [k, v] of Object.entries(snapshot)) {
      this.store.set(k, v);
    }
  }

  asAccessor(): { get: (key: string) => unknown; set: (key: string, value: unknown) => void } {
    return {
      get: (key: string) => this.get(key),
      set: (key: string, value: unknown) => this.set(key, value),
    };
  }
}

interface SessionEntry {
  value: unknown;
  expiresAt: number;
}

export interface SessionMemoryConfig {
  defaultTtlMs: number;
}

export class SessionMemory {
  private readonly store = new Map<string, SessionEntry>();
  private readonly defaultTtlMs: number;

  constructor(config: SessionMemoryConfig = { defaultTtlMs: 24 * 60 * 60 * 1000 }) {
    this.defaultTtlMs = config.defaultTtlMs;
  }

  set(key: string, value: unknown, ttlMs?: number): void {
    const expiresAt = Date.now() + (ttlMs ?? this.defaultTtlMs);
    this.store.set(key, { value, expiresAt });
  }

  get(key: string): unknown {
    const entry = this.store.get(key);
    if (!entry) return undefined;
    if (Date.now() > entry.expiresAt) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  has(key: string): boolean {
    return this.get(key) !== undefined;
  }

  delete(key: string): void {
    this.store.delete(key);
  }

  evictExpired(): number {
    const now = Date.now();
    let count = 0;
    for (const [key, entry] of this.store) {
      if (now > entry.expiresAt) {
        this.store.delete(key);
        count++;
      }
    }
    return count;
  }

  size(): number {
    this.evictExpired();
    return this.store.size;
  }
}

