import type { WorkerJobData } from '@agent-os/core';

export interface Job {
  id: string;
  name: string;
  data: WorkerJobData;
  priority: number;
  attempts: number;
  maxAttempts: number;
  createdAt: Date;
  startedAt?: Date;
}

type JobProcessor = (job: Job) => Promise<void>;

interface QueueEvents {
  completed: (job: Job) => void;
  failed: (job: Job, error: Error) => void;
  active: (job: Job) => void;
}

export class InMemoryScheduler {
  private readonly queue: Job[] = [];
  private readonly activeJobs = new Map<string, Job>();
  private readonly handlers = new Map<keyof QueueEvents, Set<(...args: unknown[]) => void>>();
  private processor: JobProcessor | null = null;
  private concurrency: number;
  private running = 0;
  private draining = false;

  constructor(private readonly name: string, concurrency = 50) {
    this.concurrency = concurrency;
  }

  add(name: string, data: WorkerJobData, opts: { priority?: number; attempts?: number } = {}): Job {
    const job: Job = {
      id: data.runId,
      name,
      data,
      priority: opts.priority ?? 0,
      attempts: 0,
      maxAttempts: opts.attempts ?? 1,
      createdAt: new Date(),
    };
    this.queue.push(job);
    this.queue.sort((a, b) => b.priority - a.priority);
    setImmediate(() => this.tick());
    return job;
  }

  process(concurrency: number, processor: JobProcessor): void {
    this.concurrency = concurrency;
    this.processor = processor;
    this.tick();
  }

  private tick(): void {
    if (!this.processor || this.draining) return;

    while (this.running < this.concurrency && this.queue.length > 0) {
      const job = this.queue.shift();
      if (!job) break;

      job.startedAt = new Date();
      job.attempts++;
      this.running++;
      this.activeJobs.set(job.id, job);

      this.emit('active', job);

      this.processor(job)
        .then(() => {
          this.running--;
          this.activeJobs.delete(job.id);
          this.emit('completed', job);
          this.tick();
        })
        .catch((err: unknown) => {
          this.running--;
          this.activeJobs.delete(job.id);

          if (job.attempts < job.maxAttempts) {
            this.queue.unshift(job);
          } else {
            this.emit('failed', job, err instanceof Error ? err : new Error(String(err)));
          }
          this.tick();
        });
    }
  }

  on<K extends keyof QueueEvents>(event: K, handler: QueueEvents[K]): () => void {
    if (!this.handlers.has(event)) this.handlers.set(event, new Set());
    this.handlers.get(event)!.add(handler as (...args: unknown[]) => void);
    return () => this.handlers.get(event)?.delete(handler as (...args: unknown[]) => void);
  }

  private emit<K extends keyof QueueEvents>(event: K, ...args: Parameters<QueueEvents[K]>): void {
    const set = this.handlers.get(event);
    if (!set) return;
    for (const handler of set) {
      try { handler(...(args as unknown[])); } catch { /* silent */ }
    }
  }

  get stats() {
    return {
      name: this.name,
      waiting: this.queue.length,
      active: this.activeJobs.size,
      concurrency: this.concurrency,
    };
  }

  drain(): void {
    this.draining = true;
  }
}

import type { ExecutionCheckpoint, Message, TokenUsage } from '@agent-os/core';
import type { AgentOSDb } from '@agent-os/db';
import { v4 as uuidv4 } from 'uuid';

export class CheckpointManager {
  constructor(private readonly db: AgentOSDb) {}

  write(
    runId: string,
    agentId: string,
    turnIndex: number,
    messages: Message[],
    tokenUsage: TokenUsage,
    agentState?: Record<string, unknown>
  ): ExecutionCheckpoint {
    const id = uuidv4();
    const now = new Date();

    const db = this.db as unknown as {
      _: { client: { prepare: (sql: string) => { run: (...args: unknown[]) => void } } };
    };

    db._.client.prepare(`
      INSERT INTO execution_checkpoints (id, run_id, agent_id, turn_index, messages_json,
        input_tokens, output_tokens, total_tokens, agent_state_json, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      id, runId, agentId, turnIndex,
      JSON.stringify(messages),
      tokenUsage.inputTokens,
      tokenUsage.outputTokens,
      tokenUsage.totalTokens,
      agentState ? JSON.stringify(agentState) : null,
      now.getTime()
    );

    db._.client.prepare(`
      UPDATE agent_runs SET checkpoint_id = ? WHERE id = ?
    `).run(id, runId);

    return {
      id,
      runId,
      agentId,
      turnIndex,
      messages,
      tokenUsage,
      agentState,
      createdAt: now,
    };
  }

  loadLatest(runId: string): ExecutionCheckpoint | null {
    const db = this.db as unknown as {
      _: { client: { prepare: (sql: string) => { get: (...args: unknown[]) => unknown } } };
    };

    const row = db._.client.prepare(`
      SELECT * FROM execution_checkpoints
      WHERE run_id = ?
      ORDER BY turn_index DESC
      LIMIT 1
    `).get(runId) as Record<string, unknown> | undefined;

    if (!row) return null;

    return {
      id: row['id'] as string,
      runId: row['run_id'] as string,
      agentId: row['agent_id'] as string,
      turnIndex: row['turn_index'] as number,
      messages: JSON.parse(row['messages_json'] as string) as Message[],
      tokenUsage: {
        inputTokens: row['input_tokens'] as number,
        outputTokens: row['output_tokens'] as number,
        totalTokens: row['total_tokens'] as number,
      },
      agentState: row['agent_state_json']
        ? (JSON.parse(row['agent_state_json'] as string) as Record<string, unknown>)
        : undefined,
      createdAt: new Date(row['created_at'] as number),
    };
  }

  loadRecoverableRuns(): Array<{
    runId: string;
    agentId: string;
    inputJson: string;
    checkpointId: string | null;
  }> {
    const db = this.db as unknown as {
      _: { client: { prepare: (sql: string) => { all: () => unknown[] } } };
    };

    return db._.client.prepare(`
      SELECT id as runId, agent_id as agentId, input_json as inputJson, checkpoint_id as checkpointId
      FROM agent_runs
      WHERE status IN ('RUNNING', 'RESUMING')
    `).all() as Array<{ runId: string; agentId: string; inputJson: string; checkpointId: string | null }>;
  }

  markResuming(runId: string): void {
    const db = this.db as unknown as {
      _: { client: { prepare: (sql: string) => { run: (...args: unknown[]) => void } } };
    };
    db._.client.prepare(`
      UPDATE agent_runs SET status = 'RESUMING' WHERE id = ?
    `).run(runId);
  }
}

import type { TokenBudgetPolicy, TokenUsage } from '@agent-os/core';
import { AgentOSError } from '@agent-os/core';

export class TokenTracker {
  private inputTokens = 0;
  private outputTokens = 0;
  private warnFired = false;

  constructor(private readonly budget: TokenBudgetPolicy | undefined) {}

  get usage(): TokenUsage {
    return {
      inputTokens: this.inputTokens,
      outputTokens: this.outputTokens,
      totalTokens: this.inputTokens + this.outputTokens,
    };
  }

  restore(usage: TokenUsage): void {
    this.inputTokens = usage.inputTokens;
    this.outputTokens = usage.outputTokens;
  }

  accumulate(usage: TokenUsage): 'ok' | 'warning' | 'exceeded' {
    this.inputTokens += usage.inputTokens;
    this.outputTokens += usage.outputTokens;
    return this.checkBudget();
  }

  private checkBudget(): 'ok' | 'warning' | 'exceeded' {
    if (!this.budget) return 'ok';
    const total = this.inputTokens + this.outputTokens;

    if (total > this.budget.maxTotalTokens) {
      if (this.budget.onBudgetExceeded === 'hard_stop') {
        throw AgentOSError.budgetExceeded(this.usage, this.budget.maxTotalTokens);
      }
      return 'exceeded';
    }

    if (this.budget.warnAt !== undefined && total >= this.budget.warnAt && !this.warnFired) {
      this.warnFired = true;
      return 'warning';
    }

    return 'ok';
  }

  isBudgetExceeded(): boolean {
    if (!this.budget) return false;
    return this.inputTokens + this.outputTokens > this.budget.maxTotalTokens;
  }
}

import { workerData, parentPort } from 'worker_threads';
import { v4 as uuidv4 } from 'uuid';
import type {
  WorkerJobData,
  WorkerMessage,
  AgentEvent,
  ExecutionCheckpoint,
  AgentRun,
  Message,
  ToolCall,
  AdapterInstance,
} from '@agent-os/core';
import { AgentOSError, MAX_TURNS } from '@agent-os/core';
import { TokenTracker } from './token-tracker.js';

if (!parentPort) {
  throw new Error('worker-entry must be run as a Worker thread');
}

const port = parentPort;
const job = workerData as WorkerJobData;

function sendEvent(event: Omit<AgentEvent, 'sequenceNumber'>): void {
  port.postMessage({ type: 'event', event } satisfies WorkerMessage);
}

function sendCheckpoint(checkpoint: ExecutionCheckpoint): void {
  port.postMessage({ type: 'checkpoint', checkpoint } satisfies WorkerMessage);
}

function sendDone(run: AgentRun): void {
  port.postMessage({ type: 'done', run } satisfies WorkerMessage);
}

function sendError(error: string): void {
  port.postMessage({ type: 'error', error } satisfies WorkerMessage);
}

async function buildAdapter(config: WorkerJobData['adapterConfig']): Promise<AdapterInstance> {
  const { AnthropicAdapter } = await import('@agent-os/adapters');

  if (config.provider === 'anthropic') {
    return new AnthropicAdapter({
      apiKey: config.apiKey ?? process.env['ANTHROPIC_API_KEY'],
      model: config.model,
      maxTokens: config.maxTokens,
      temperature: config.temperature,
    });
  }

  if (config.provider === 'openai' || config.provider === 'local') {
    const { OpenAIAdapter } = await import('@agent-os/adapters');
    return new OpenAIAdapter({
      apiKey: config.apiKey ?? process.env['OPENAI_API_KEY'],
      model: config.model,
      baseURL: config.baseURL,
      maxTokens: config.maxTokens,
      temperature: config.temperature,
    });
  }

  throw AgentOSError.adapterError(config.provider, `Unknown provider: ${config.provider}`);
}

async function run(): Promise<void> {
  const { runId, agentId, input, systemPrompt, adapterConfig, tokenBudget, checkpoint } = job;

  const tracker = new TokenTracker(tokenBudget);
  let messages: Message[] = [];
  let startTurn = 0;

  if (checkpoint) {
    messages = checkpoint.messages;
    startTurn = checkpoint.turnIndex + 1;
    tracker.restore(checkpoint.tokenUsage);
    sendEvent({
      id: uuidv4(), runId, agentId, type: 'run.resuming',
      data: { fromTurn: startTurn, checkpoint: checkpoint.id },
      timestamp: new Date(),
    });
  } else {
    messages = [{ role: 'user', content: JSON.stringify(input) }];
    sendEvent({
      id: uuidv4(), runId, agentId, type: 'run.started',
      data: { input },
      timestamp: new Date(),
    });
  }

  let adapter: AdapterInstance;
  try {
    adapter = await buildAdapter(adapterConfig);
  } catch (err) {
    sendError(err instanceof Error ? err.message : String(err));
    return;
  }

  const run: AgentRun = {
    id: runId,
    agentId,
    status: 'RUNNING',
    input,
    createdAt: new Date(),
    startedAt: new Date(),
    tokenUsage: tracker.usage,
  };

  try {
    for (let turn = startTurn; turn < MAX_TURNS; turn++) {
      sendEvent({
        id: uuidv4(), runId, agentId, type: 'turn.started',
        data: { turn },
        timestamp: new Date(),
      });

      const result = await adapter.run(messages, { systemPrompt });

      const budgetStatus = tracker.accumulate(result.usage);

      sendEvent({
        id: uuidv4(), runId, agentId, type: 'token.usage',
        data: { usage: result.usage, cumulative: tracker.usage, turn },
        timestamp: new Date(),
      });

      if (budgetStatus === 'warning') {
        sendEvent({
          id: uuidv4(), runId, agentId, type: 'budget.warning',
          data: { usage: tracker.usage },
          timestamp: new Date(),
        });
      }

      sendEvent({
        id: uuidv4(), runId, agentId, type: 'turn.completed',
        data: { turn, stopReason: result.stopReason, contentLength: result.content.length },
        timestamp: new Date(),
      });

      const cpMessages = [...messages, { role: 'assistant' as const, content: result.content }];
      const checkpoint: ExecutionCheckpoint = {
        id: uuidv4(),
        runId, agentId,
        turnIndex: turn,
        messages: cpMessages,
        tokenUsage: tracker.usage,
        createdAt: new Date(),
      };
      sendCheckpoint(checkpoint);

      if (result.stopReason === 'end_turn' || result.toolCalls.length === 0) {
        run.status = 'COMPLETED';
        run.output = { content: result.content };
        run.tokenUsage = tracker.usage;
        run.completedAt = new Date();

        sendEvent({
          id: uuidv4(), runId, agentId, type: 'run.completed',
          data: { output: run.output, tokenUsage: tracker.usage },
          timestamp: new Date(),
        });

        sendDone(run);
        return;
      }

      messages.push({ role: 'assistant', content: result.content, toolCalls: result.toolCalls });

      for (const tc of result.toolCalls) {
        sendEvent({
          id: uuidv4(), runId, agentId, type: 'tool.called',
          data: { toolName: tc.name, input: tc.input },
          timestamp: new Date(),
        });
        messages.push({
          role: 'tool',
          content: JSON.stringify({ error: 'Tool execution happens in main thread' }),
          toolCallId: tc.id,
        });
        sendEvent({
          id: uuidv4(), runId, agentId, type: 'tool.result',
          data: { toolName: tc.name, success: false, note: 'tool_dispatch_pending' },
          timestamp: new Date(),
        });
      }
    }

    run.status = 'FAILED';
    run.error = `Exceeded maximum turns (${MAX_TURNS})`;
    run.tokenUsage = tracker.usage;
    run.completedAt = new Date();

    sendEvent({
      id: uuidv4(), runId, agentId, type: 'run.failed',
      data: { error: run.error },
      timestamp: new Date(),
    });
    sendDone(run);

  } catch (err) {
    const error = err instanceof Error ? err.message : String(err);
    const isBudget = err instanceof AgentOSError && err.agentError.code === 'BUDGET_EXCEEDED';

    run.status = 'FAILED';
    run.error = error;
    run.tokenUsage = tracker.usage;
    run.completedAt = new Date();

    sendEvent({
      id: uuidv4(), runId, agentId,
      type: isBudget ? 'budget.exceeded' : 'run.failed',
      data: { error, usage: tracker.usage },
      timestamp: new Date(),
    });
    sendDone(run);
  }
}

run().catch((err) => {
  sendError(err instanceof Error ? err.message : String(err));
});

import { Worker } from 'worker_threads';
import { dirname, resolve } from 'path';
import { fileURLToPath } from 'url';
import { v4 as uuidv4 } from 'uuid';
import type {
  AgentEvent,
  AgentRun,
  AgentRunnerConfig,
  AgentResult,
  ExecutionCheckpoint,
  WorkerJobData,
  TokenBudgetPolicy,
} from '@agent-os/core';
import { AgentOSError, CONCURRENCY_DEFAULTS, AGENT_OS_VERSION } from '@agent-os/core';
import type { AgentOSDb } from '@agent-os/db';
import type { EventStore } from '@agent-os/events';
import { CheckpointManager } from './checkpoint-manager.js';
import { InMemoryScheduler } from './scheduler.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const WORKER_ENTRY = resolve(__dirname, 'worker-entry.ts');

export interface AgentRunnerOptions extends AgentRunnerConfig {
  db: AgentOSDb;
  eventStore: EventStore;
  concurrencyLimit?: number;
  defaultTokenBudget?: TokenBudgetPolicy;
}

export interface RunInput {
  agentId: string;
  input: Record<string, unknown>;
  systemPrompt?: string;
  tokenBudget?: TokenBudgetPolicy;
  metadata?: Record<string, unknown>;
}

export class AgentRunner {
  private readonly scheduler: InMemoryScheduler;
  private readonly checkpoints: CheckpointManager;
  private readonly db: AgentOSDb;
  private readonly eventStore: EventStore;
  private readonly maxConcurrency: number;
  private activeRuns = 0;

  constructor(private readonly options: AgentRunnerOptions) {
    this.maxConcurrency = options.concurrencyLimit ?? CONCURRENCY_DEFAULTS.maxConcurrentRuns;
    this.db = options.db;
    this.eventStore = options.eventStore;
    this.checkpoints = new CheckpointManager(this.db);
    this.scheduler = new InMemoryScheduler('agent-os:executions', this.maxConcurrency);

    this.scheduler.process(this.maxConcurrency, async (job) => {
      await this.runWorker(job.data);
    });

    this.scheduler.on('failed', (job, err) => {
      console.error(`[AgentRunner] Job ${job.id} failed: ${err.message}`);
    });
  }

  async run(input: RunInput): Promise<AgentResult> {
    if (this.activeRuns >= this.maxConcurrency) {
      throw AgentOSError.concurrencyLimit(this.maxConcurrency, this.activeRuns);
    }

    const runId = uuidv4();
    const now = new Date();

    const rawDb = this.db as unknown as { _: { client: { prepare: (sql: string) => { run: (...args: unknown[]) => void } } } };
    rawDb._.client.prepare(`
      INSERT INTO agent_runs (id, agent_id, status, input_json, created_at, started_at)
      VALUES (?, ?, 'RUNNING', ?, ?, ?)
    `).run(runId, input.agentId, JSON.stringify(input.input), now.getTime(), now.getTime());

    const jobData: WorkerJobData = {
      runId,
      agentId: input.agentId,
      input: input.input,
      systemPrompt: input.systemPrompt,
      adapterConfig: {
        provider: this.options.adapter.provider,
        model: this.options.adapter.model,
      },
      tokenBudget: input.tokenBudget ?? this.options.defaultTokenBudget,
      metadata: input.metadata,
    };

    return new Promise<AgentResult>((resolve, reject) => {
      this.scheduler.add('run', jobData, { priority: 0 });

      const resultRef = { run: null as AgentRun | null };

      const cleanup = this.eventStore.on('run.completed' as never, (ev: AgentEvent) => {
        if (ev.runId === runId) {
          cleanup();
          const run = resultRef.run;
          if (run) {
            resolve({
              runId: run.id,
              agentId: run.agentId,
              status: run.status,
              output: run.output,
              tokenUsage: run.tokenUsage ?? { inputTokens: 0, outputTokens: 0, totalTokens: 0 },
              durationMs: run.completedAt && run.startedAt
                ? run.completedAt.getTime() - run.startedAt.getTime()
                : 0,
            });
          }
        }
      });
    });
  }

  private async runWorker(jobData: WorkerJobData): Promise<void> {
    this.activeRuns++;

    return new Promise<void>((resolve, reject) => {
      const worker = new Worker(WORKER_ENTRY, {
        execArgv: ['--import', 'tsx'],
        workerData: jobData,
        resourceLimits: {
          maxOldGenerationSizeMb: CONCURRENCY_DEFAULTS.workerMemoryLimitMb,
          maxYoungGenerationSizeMb: CONCURRENCY_DEFAULTS.workerYoungMemoryLimitMb,
        },
      });

      const rawDb = this.db as unknown as {
        _: { client: { prepare: (sql: string) => { run: (...args: unknown[]) => void } } };
      };

      worker.on('message', (msg: { type: string; event?: AgentEvent; checkpoint?: ExecutionCheckpoint; run?: AgentRun; error?: string }) => {
        if (msg.type === 'event' && msg.event) {
          this.eventStore.appendSync(msg.event);
          this.options.onEvent?.(msg.event);
        }

        if (msg.type === 'checkpoint' && msg.checkpoint) {
          const cp = msg.checkpoint;
          this.checkpoints.write(
            cp.runId, cp.agentId, cp.turnIndex,
            cp.messages, cp.tokenUsage, cp.agentState
          );

          const cpEvent: Omit<AgentEvent, 'sequenceNumber'> = {
            id: uuidv4(),
            runId: cp.runId,
            agentId: cp.agentId,
            type: 'checkpoint.created',
            data: { checkpointId: cp.id, turnIndex: cp.turnIndex, tokenUsage: cp.tokenUsage },
            timestamp: new Date(),
          };
          this.eventStore.appendSync(cpEvent);
        }

        if (msg.type === 'done' && msg.run) {
          const run = msg.run;
          rawDb._.client.prepare(`
            UPDATE agent_runs SET
              status = ?,
              output_json = ?,
              error_message = ?,
              input_tokens = ?,
              output_tokens = ?,
              total_tokens = ?,
              completed_at = ?
            WHERE id = ?
          `).run(
            run.status,
            run.output ? JSON.stringify(run.output) : null,
            run.error ?? null,
            run.tokenUsage?.inputTokens ?? 0,
            run.tokenUsage?.outputTokens ?? 0,
            run.tokenUsage?.totalTokens ?? 0,
            run.completedAt ? run.completedAt.getTime() : null,
            run.id
          );
        }

        if (msg.type === 'error') {
          console.error(`[Worker] ${jobData.runId}: ${msg.error}`);
          rawDb._.client.prepare(`
            UPDATE agent_runs SET status = 'FAILED', error_message = ?, completed_at = ? WHERE id = ?
          `).run(msg.error, Date.now(), jobData.runId);
        }
      });

      worker.on('exit', (code) => {
        this.activeRuns--;
        this.eventStore.clearRun(jobData.runId);
        if (code === 0) {
          resolve();
        } else {
          reject(new Error(`Worker exited with code ${code}`));
        }
      });

      worker.on('error', (err) => {
        this.activeRuns--;
        rawDb._.client.prepare(`
          UPDATE agent_runs SET status = 'FAILED', error_message = ?, completed_at = ? WHERE id = ?
        `).run(err.message, Date.now(), jobData.runId);
        reject(err);
      });
    });
  }

  async recoverCrashedRuns(): Promise<number> {
    const recoverable = this.checkpoints.loadRecoverableRuns();
    let count = 0;

    for (const { runId, agentId, inputJson, checkpointId: _cpId } of recoverable) {
      const checkpoint = this.checkpoints.loadLatest(runId);
      this.checkpoints.markResuming(runId);

      const input = JSON.parse(inputJson) as Record<string, unknown>;
      const jobData: WorkerJobData = {
        runId,
        agentId,
        input,
        adapterConfig: {
          provider: this.options.adapter.provider,
          model: this.options.adapter.model,
        },
        checkpoint: checkpoint ?? undefined,
      };

      this.scheduler.add('recover', jobData, { priority: 10 });
      count++;

      const recoveryEvent: Omit<AgentEvent, 'sequenceNumber'> = {
        id: uuidv4(),
        runId,
        agentId,
        type: 'run.resuming',
        data: {
          fromCheckpoint: checkpoint?.id,
          fromTurn: checkpoint?.turnIndex ?? 0,
          recoveryAt: new Date().toISOString(),
        },
        timestamp: new Date(),
      };
      this.eventStore.appendSync(recoveryEvent);
    }

    return count;
  }

  get stats() {
    return {
      activeRuns: this.activeRuns,
      maxConcurrency: this.maxConcurrency,
      scheduler: this.scheduler.stats,
    };
  }
}

import type { AgentEvent, AgentEventType } from '@agent-os/core';

type EventHandler = (event: AgentEvent) => void | Promise<void>;

export class EventBus {
  private readonly handlers = new Map<string, Set<EventHandler>>();
  private readonly allHandlers = new Set<EventHandler>();
  private sequenceCounters = new Map<string, number>();

  on(type: AgentEventType | '*', handler: EventHandler): () => void {
    if (type === '*') {
      this.allHandlers.add(handler);
      return () => this.allHandlers.delete(handler);
    }
    if (!this.handlers.has(type)) {
      this.handlers.set(type, new Set());
    }
    this.handlers.get(type)!.add(handler);
    return () => this.handlers.get(type)?.delete(handler);
  }

  async emit(event: Omit<AgentEvent, 'sequenceNumber'>): Promise<AgentEvent> {
    const counter = this.sequenceCounters.get(event.runId) ?? 0;
    this.sequenceCounters.set(event.runId, counter + 1);

    const fullEvent: AgentEvent = { ...event, sequenceNumber: counter };
    const typeHandlers = this.handlers.get(event.type) ?? new Set();
    const promises: Promise<void>[] = [];

    for (const handler of [...typeHandlers, ...this.allHandlers]) {
      const result = handler(fullEvent);
      if (result instanceof Promise) promises.push(result);
    }

    await Promise.allSettled(promises);
    return fullEvent;
  }

  clearRun(runId: string): void {
    this.sequenceCounters.delete(runId);
  }

  removeAllHandlers(): void {
    this.handlers.clear();
    this.allHandlers.clear();
    this.sequenceCounters.clear();
  }
}

