import type { AgentEvent, AgentEventType } from '@agent-os/core';
import type { AgentOSDb } from '@agent-os/db';
import { redactEventData } from './redaction.js';

type EventHandler = (event: AgentEvent) => void;

type RawDb = {
  _: {
    client: {
      prepare: (sql: string) => {
        run: (...args: unknown[]) => void;
      };
    };
  };
};

export class EventStore {
  private readonly handlers = new Map<string, Set<EventHandler>>();
  private readonly allHandlers = new Set<EventHandler>();
  private readonly sequenceCounters = new Map<string, number>();
  private readonly sqlite: RawDb['_']['client'];

  constructor(db: AgentOSDb) {
    this.sqlite = (db as unknown as RawDb)._.client;
  }

  on(type: AgentEventType | '*', handler: EventHandler): () => void {
    if (type === '*') {
      this.allHandlers.add(handler);
      return () => this.allHandlers.delete(handler);
    }
    if (!this.handlers.has(type)) {
      this.handlers.set(type, new Set());
    }
    this.handlers.get(type)!.add(handler);
    return () => this.handlers.get(type)?.delete(handler);
  }

  appendSync(event: Omit<AgentEvent, 'sequenceNumber'>): AgentEvent {
    const seq = this.sequenceCounters.get(event.runId) ?? 0;
    this.sequenceCounters.set(event.runId, seq + 1);

    const { data: redactedData, redactionIncomplete } = redactEventData(event.data);

    const fullEvent: AgentEvent = {
      ...event,
      data: redactedData,
      sequenceNumber: seq,
      redactionIncomplete,
    };

    try {
      this.sqlite.prepare(
        `INSERT INTO agent_events
           (id, run_id, agent_id, type, data_json, timestamp, sequence_number, redaction_incomplete)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      ).run(
        fullEvent.id,
        fullEvent.runId,
        fullEvent.agentId,
        fullEvent.type,
        JSON.stringify(fullEvent.data),
        fullEvent.timestamp.getTime(),
        fullEvent.sequenceNumber,
        fullEvent.redactionIncomplete ? 1 : 0
      );
    } catch {
    }

    this.broadcast(fullEvent);
    return fullEvent;
  }

  append(event: Omit<AgentEvent, 'sequenceNumber'>): AgentEvent {
    return this.appendSync(event);
  }

  private broadcast(event: AgentEvent): void {
    const typeHandlers = this.handlers.get(event.type) ?? new Set();
    for (const handler of [...typeHandlers, ...this.allHandlers]) {
      try { handler(event); } catch { /* handler errors are silent */ }
    }
  }

  clearRun(runId: string): void {
    this.sequenceCounters.delete(runId);
  }

  initSequenceFromDb(runId: string, lastSeq: number): void {
    this.sequenceCounters.set(runId, lastSeq + 1);
  }
}

import { Worker } from 'worker_threads';
import { dirname, resolve } from 'path';
import { fileURLToPath } from 'url';
import { v4 as uuidv4 } from 'uuid';
import type {
  AgentEvent,
  AgentRun,
  AgentRunnerConfig,
  AgentResult,
  ExecutionCheckpoint,
  WorkerJobData,
  TokenBudgetPolicy,
} from '@agent-os/core';
import { AgentOSError, CONCURRENCY_DEFAULTS } from '@agent-os/core';
import type { AgentOSDb } from '@agent-os/db';
import type { EventStore } from '@agent-os/events';
import { CheckpointManager } from './checkpoint-manager.js';
import { InMemoryScheduler } from './scheduler.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const WORKER_ENTRY = resolve(__dirname, 'worker-entry.ts');

type RawDb = {
  _: { client: { prepare: (sql: string) => { run: (...args: unknown[]) => void } } };
};

export interface AgentRunnerOptions extends AgentRunnerConfig {
  db: AgentOSDb;
  eventStore: EventStore;
  concurrencyLimit?: number;
  defaultTokenBudget?: TokenBudgetPolicy;
}

export interface RunInput {
  agentId: string;
  input: Record<string, unknown>;
  systemPrompt?: string;
  tokenBudget?: TokenBudgetPolicy;
  metadata?: Record<string, unknown>;
}

interface PendingRun {
  resolve: (result: AgentResult) => void;
  reject: (err: Error) => void;
  startedAt: number;
}

export class AgentRunner {
  private readonly scheduler: InMemoryScheduler;
  private readonly checkpoints: CheckpointManager;
  private readonly db: AgentOSDb;
  private readonly eventStore: EventStore;
  private readonly maxConcurrency: number;
  private readonly pending = new Map<string, PendingRun>();
  private activeRuns = 0;
  private readonly sqlite: RawDb['_']['client'];

  constructor(private readonly options: AgentRunnerOptions) {
    this.maxConcurrency = options.concurrencyLimit ?? CONCURRENCY_DEFAULTS.maxConcurrentRuns;
    this.db = options.db;
    this.eventStore = options.eventStore;
    this.checkpoints = new CheckpointManager(this.db);
    this.sqlite = (this.db as unknown as RawDb)._.client;

    this.scheduler = new InMemoryScheduler('agent-os:executions', this.maxConcurrency);
    this.scheduler.process(this.maxConcurrency, async (job) => {
      await this.runWorker(job.data);
    });

    this.scheduler.on('failed', (job, err) => {
      const p = this.pending.get(job.id);
      if (p) {
        this.pending.delete(job.id);
        p.reject(err);
      }
    });
  }

  async run(input: RunInput): Promise<AgentResult> {
    if (this.activeRuns >= this.maxConcurrency) {
      throw AgentOSError.concurrencyLimit(this.maxConcurrency, this.activeRuns);
    }

    const runId = uuidv4();
    const now = Date.now();

    this.sqlite.prepare(`
      INSERT INTO agent_runs (id, agent_id, status, input_json, created_at, started_at)
      VALUES (?, ?, 'RUNNING', ?, ?, ?)
    `).run(runId, input.agentId, JSON.stringify(input.input), now, now);

    const jobData: WorkerJobData = {
      runId,
      agentId: input.agentId,
      input: input.input,
      systemPrompt: input.systemPrompt,
      adapterConfig: {
        provider: this.options.adapter.provider,
        model: this.options.adapter.model,
      },
      tokenBudget: input.tokenBudget ?? this.options.defaultTokenBudget,
      metadata: input.metadata,
    };

    return new Promise<AgentResult>((resolve, reject) => {
      this.pending.set(runId, { resolve, reject, startedAt: now });
      this.scheduler.add('run', jobData, { priority: 0 });
    });
  }

  private async runWorker(jobData: WorkerJobData): Promise<void> {
    this.activeRuns++;

    const worker = new Worker(WORKER_ENTRY, {
      execArgv: ['--import', 'tsx'],
      workerData: jobData,
      resourceLimits: {
        maxOldGenerationSizeMb: CONCURRENCY_DEFAULTS.workerMemoryLimitMb,
        maxYoungGenerationSizeMb: CONCURRENCY_DEFAULTS.workerYoungMemoryLimitMb,
      },
    });

    let finalRun: AgentRun | null = null;

    worker.on('message', (msg: {
      type: string;
      event?: AgentEvent;
      checkpoint?: ExecutionCheckpoint;
      run?: AgentRun;
      error?: string;
    }) => {
      if (msg.type === 'event' && msg.event) {
        this.eventStore.appendSync(msg.event);
        this.options.onEvent?.(msg.event);
      }

      if (msg.type === 'checkpoint' && msg.checkpoint) {
        const cp = msg.checkpoint;
        this.checkpoints.write(
          cp.runId, cp.agentId, cp.turnIndex,
          cp.messages, cp.tokenUsage, cp.agentState
        );
        const cpEvent: Omit<AgentEvent, 'sequenceNumber'> = {
          id: uuidv4(), runId: cp.runId, agentId: cp.agentId,
          type: 'checkpoint.created',
          data: { checkpointId: cp.id, turnIndex: cp.turnIndex, tokenUsage: cp.tokenUsage },
          timestamp: new Date(),
        };
        this.eventStore.appendSync(cpEvent);
      }

      if (msg.type === 'done' && msg.run) {
        finalRun = msg.run;
        const run = msg.run;
        this.sqlite.prepare(`
          UPDATE agent_runs SET
            status = ?, output_json = ?, error_message = ?,
            input_tokens = ?, output_tokens = ?, total_tokens = ?, completed_at = ?
          WHERE id = ?
        `).run(
          run.status,
          run.output ? JSON.stringify(run.output) : null,
          run.error ?? null,
          run.tokenUsage?.inputTokens ?? 0,
          run.tokenUsage?.outputTokens ?? 0,
          run.tokenUsage?.totalTokens ?? 0,
          run.completedAt ? run.completedAt.getTime() : null,
          run.id
        );
      }

      if (msg.type === 'error') {
        this.sqlite.prepare(
          `UPDATE agent_runs SET status='FAILED', error_message=?, completed_at=? WHERE id=?`
        ).run(msg.error, Date.now(), jobData.runId);
      }
    });

    await new Promise<void>((resolve, reject) => {
      worker.on('exit', (code) => {
        this.activeRuns--;
        this.eventStore.clearRun(jobData.runId);

        const p = this.pending.get(jobData.runId);
        if (p && finalRun) {
          this.pending.delete(jobData.runId);
          const result: AgentResult = {
            runId: finalRun.id,
            agentId: finalRun.agentId,
            status: finalRun.status,
            output: finalRun.output,
            error: finalRun.error,
            tokenUsage: finalRun.tokenUsage ?? { inputTokens: 0, outputTokens: 0, totalTokens: 0 },
            durationMs: finalRun.completedAt && finalRun.startedAt
              ? finalRun.completedAt.getTime() - finalRun.startedAt.getTime()
              : 0,
          };
          p.resolve(result);
          resolve();
        } else if (p) {
          this.pending.delete(jobData.runId);
          const err = new Error(`Worker exited with code ${code} without sending done`);
          p.reject(err);
          reject(err);
        } else {
          if (code === 0) resolve();
          else reject(new Error(`Worker exited with code ${code}`));
        }
      });

      worker.on('error', (err) => {
        this.activeRuns--;
        this.sqlite.prepare(
          `UPDATE agent_runs SET status='FAILED', error_message=?, completed_at=? WHERE id=?`
        ).run(err.message, Date.now(), jobData.runId);

        const p = this.pending.get(jobData.runId);
        if (p) {
          this.pending.delete(jobData.runId);
          p.reject(err);
        }
        reject(err);
      });
    });
  }

  async recoverCrashedRuns(): Promise<number> {
    const recoverable = this.checkpoints.loadRecoverableRuns();
    let count = 0;

    for (const { runId, agentId, inputJson } of recoverable) {
      const checkpoint = this.checkpoints.loadLatest(runId);
      this.checkpoints.markResuming(runId);

      const input = JSON.parse(inputJson) as Record<string, unknown>;
      const jobData: WorkerJobData = {
        runId, agentId, input,
        adapterConfig: {
          provider: this.options.adapter.provider,
          model: this.options.adapter.model,
        },
        checkpoint: checkpoint ?? undefined,
      };

      this.scheduler.add('recover', jobData, { priority: 10 });
      count++;

      const recoveryEvent: Omit<AgentEvent, 'sequenceNumber'> = {
        id: uuidv4(), runId, agentId, type: 'run.resuming',
        data: {
          fromCheckpoint: checkpoint?.id,
          fromTurn: checkpoint?.turnIndex ?? 0,
          recoveryAt: new Date().toISOString(),
        },
        timestamp: new Date(),
      };
      this.eventStore.appendSync(recoveryEvent);
    }

    return count;
  }

  get stats() {
    return {
      activeRuns: this.activeRuns,
      maxConcurrency: this.maxConcurrency,
      pendingCount: this.pending.size,
      scheduler: this.scheduler.stats,
    };
  }
}

import type {
  AdapterRunConfig,
  AdapterResult,
  AdapterFeature,
  Message,
  StreamChunk,
  ToolCall,
  ToolDefinition,
} from '@agent-os/core';
import { AgentOSError } from '@agent-os/core';
import { BaseAdapter } from './base.js';

interface OpenAIMessage {
  role: 'system' | 'user' | 'assistant' | 'tool';
  content: string | null;
  tool_call_id?: string;
  tool_calls?: Array<{
    id: string;
    type: 'function';
    function: { name: string; arguments: string };
  }>;
}

interface OpenAIChatResponse {
  id: string;
  choices: Array<{
    message: {
      role: string;
      content: string | null;
      tool_calls?: Array<{
        id: string;
        type: string;
        function: { name: string; arguments: string };
      }>;
    };
    finish_reason: string;
  }>;
  usage: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

export interface OpenAIAdapterConfig {
  apiKey?: string;
  model?: string;
  baseURL?: string;
  maxTokens?: number;
  temperature?: number;
}

export class OpenAIAdapter extends BaseAdapter {
  readonly provider = 'openai';
  readonly model: string;
  private readonly apiKey: string;
  private readonly baseURL: string;
  private readonly defaultMaxTokens: number;
  private readonly defaultTemperature: number;

  constructor(config: OpenAIAdapterConfig = {}) {
    super();
    const apiKey = config.apiKey ?? process.env['OPENAI_API_KEY'];
    if (!apiKey) {
      throw AgentOSError.adapterError('openai', 'OPENAI_API_KEY is required');
    }
    this.apiKey = apiKey;
    this.model = config.model ?? 'gpt-4o';
    this.baseURL = config.baseURL ?? 'https://api.openai.com/v1';
    this.defaultMaxTokens = config.maxTokens ?? 4096;
    this.defaultTemperature = config.temperature ?? 1.0;
  }

  protected override supportedFeatures(): AdapterFeature[] {
    return ['streaming', 'tools', 'vision', 'json_mode'];
  }

  async run(messages: Message[], config: AdapterRunConfig): Promise<AdapterResult> {
    const body: Record<string, unknown> = {
      model: this.model,
      max_tokens: config.maxTokens ?? this.defaultMaxTokens,
      temperature: config.temperature ?? this.defaultTemperature,
      messages: this.formatMessages(messages, config.systemPrompt),
    };

    if (config.tools && config.tools.length > 0) {
      body['tools'] = this.formatTools(config.tools);
    }

    try {
      const response = await fetch(`${this.baseURL}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${this.apiKey}`,
        },
        body: JSON.stringify(body),
      });

      if (!response.ok) {
        const text = await response.text();
        throw new Error(`OpenAI API error ${response.status}: ${text}`);
      }

      const data = (await response.json()) as OpenAIChatResponse;
      const choice = data.choices[0];
      if (!choice) throw new Error('No choices in response');

      const content = choice.message.content ?? '';
      const toolCalls: ToolCall[] = (choice.message.tool_calls ?? []).map((tc) => ({
        id: tc.id,
        name: tc.function.name,
        input: JSON.parse(tc.function.arguments) as Record<string, unknown>,
      }));

      return {
        content,
        toolCalls,
        stopReason: this.mapStopReason(choice.finish_reason),
        usage: {
          inputTokens: data.usage.prompt_tokens,
          outputTokens: data.usage.completion_tokens,
          totalTokens: data.usage.total_tokens,
        },
      };
    } catch (err) {
      throw AgentOSError.adapterError('openai', `API call failed: ${String(err)}`, err);
    }
  }

  async *stream(messages: Message[], config: AdapterRunConfig): AsyncGenerator<StreamChunk> {
    const body: Record<string, unknown> = {
      model: this.model,
      max_tokens: config.maxTokens ?? this.defaultMaxTokens,
      temperature: config.temperature ?? this.defaultTemperature,
      messages: this.formatMessages(messages, config.systemPrompt),
      stream: true,
    };

    try {
      const response = await fetch(`${this.baseURL}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${this.apiKey}`,
        },
        body: JSON.stringify(body),
      });

      if (!response.ok || !response.body) {
        throw new Error(`OpenAI streaming error: ${response.status}`);
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() ?? '';

        for (const line of lines) {
          if (!line.startsWith('data: ')) continue;
          const data = line.slice(6).trim();
          if (data === '[DONE]') {
            yield { type: 'stop', stopReason: 'end_turn' };
            return;
          }
          try {
            const chunk = JSON.parse(data) as { choices: Array<{ delta: { content?: string }; finish_reason?: string }> };
            const delta = chunk.choices[0]?.delta;
            if (delta?.content) yield { type: 'text', text: delta.content };
          } catch { /* skip malformed */ }
        }
      }
    } catch (err) {
      throw AgentOSError.adapterError('openai', `Streaming failed: ${String(err)}`, err);
    }
  }

  private formatMessages(messages: Message[], systemPrompt?: string): OpenAIMessage[] {
    const result: OpenAIMessage[] = [];
    if (systemPrompt) result.push({ role: 'system', content: systemPrompt });
    for (const m of messages) {
      if (m.role === 'tool') {
        result.push({ role: 'tool', content: m.content, tool_call_id: m.toolCallId ?? 'unknown' });
      } else {
        result.push({ role: m.role as 'user' | 'assistant', content: m.content });
      }
    }
    return result;
  }

  private formatTools(tools: ToolDefinition[]): unknown[] {
    return tools.map((t) => ({
      type: 'function',
      function: {
        name: t.name,
        description: t.description,
        parameters: { type: 'object', ...t.inputSchema },
      },
    }));
  }

  private mapStopReason(reason: string): AdapterResult['stopReason'] {
    switch (reason) {
      case 'tool_calls': return 'tool_use';
      case 'length': return 'max_tokens';
      case 'stop': return 'end_turn';
      default: return 'end_turn';
    }
  }
}

import type {
  AdapterRunConfig,
  AdapterResult,
  AdapterFeature,
  Message,
  StreamChunk,
} from '@agent-os/core';
import { AgentOSError } from '@agent-os/core';
import { BaseAdapter } from './base.js';
import { OpenAIAdapter } from './openai.js';

export interface LocalAdapterConfig {
  baseURL?: string;
  model?: string;
  apiKey?: string;
  maxTokens?: number;
  temperature?: number;
}

export class LocalAdapter extends BaseAdapter {
  readonly provider = 'local';
  readonly model: string;
  private readonly delegate: OpenAIAdapter;

  constructor(config: LocalAdapterConfig = {}) {
    super();
    const baseURL = config.baseURL ?? process.env['LOCAL_LLM_URL'] ?? 'http://localhost:11434/v1';
    const model = config.model ?? process.env['LOCAL_LLM_MODEL'] ?? 'mistral';
    this.model = model;

    try {
      this.delegate = new OpenAIAdapter({
        apiKey: config.apiKey ?? process.env['LOCAL_LLM_API_KEY'] ?? 'local',
        model,
        baseURL,
        maxTokens: config.maxTokens,
        temperature: config.temperature,
      });
    } catch {
      throw AgentOSError.adapterError(
        'local',
        'Could not initialize local adapter. Ensure LOCAL_LLM_URL and LOCAL_LLM_MODEL are set.'
      );
    }
  }

  protected override supportedFeatures(): AdapterFeature[] {
    return ['streaming'];
  }

  async run(messages: Message[], config: AdapterRunConfig): Promise<AdapterResult> {
    try {
      return await this.delegate.run(messages, config);
    } catch (err) {
      throw AgentOSError.adapterError('local', `Local LLM call failed: ${String(err)}`, err);
    }
  }

  async *stream(messages: Message[], config: AdapterRunConfig): AsyncGenerator<StreamChunk> {
    try {
      yield* this.delegate.stream(messages, config);
    } catch (err) {
      throw AgentOSError.adapterError('local', `Local LLM stream failed: ${String(err)}`, err);
    }
  }
}

